(* [comment removed for export] *)
Definition hp_k_exit (A0 : Z) (ra sp gp tp s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t5 t6 : word) (F : bvmap 5 word) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (a0' a1' t3' t4' : word) (F' : bvmap 5 word) (fc' : bv 32),
    ms' = MS (mkR ra sp gp tp (Z_to_bv 64 0) (Z_to_bv 64 11) (Z_to_bv 64 (A0 + 21)) s0 s1 a0' a1' a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
                  t3' t4' t5 t6)
             F' (Z_to_bv 64 0xc305c) fc' None m (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc'.

(* [comment removed for export] *)
Lemma hp_k_loop : forall (n : nat) (kk : Z) (p : hpp) (A0 : Z)
    (ra sp gp tp s0 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = 21 - kk -> 0 <= kk -> (1 <= n)%nat -> hp_ok p -> frm0 fc ->
  hp_DS p <= A0 -> A0 + 21 <= hp_DS p + hp_N p ->
  wr_at asegs m (hp_DS p) (hp_N p) -> acc asegs m (hp_DS p) (hp_N p) ->
  wr_at asegs m (hp_SP p) 44 -> acc asegs m (hp_SP p) 44 -> wr_at asegs m (hp_RR p) 1024 -> acc asegs m (hp_RR p) 1024 -> mem_inv asegs m ->
  evt asegs (hp_k_exit A0 ra sp gp tp s0 (Z_to_bv 64 (hp_S1 p)) a2 a3 a4 a5 a6 a7
               (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 (-10)) (Z_to_bv 64 (hp_h p)) (Z_to_bv 64 21) (Z_to_bv 64 65296) (Z_to_bv 64 2147450880)
               (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_w p)) (Z_to_bv 64 10) (Z_to_bv 64 (hp_SP p)) (Z_to_bv 64 11) (Z_to_bv 64 (hp_wpl p * 4)) F m)
    (MS (mkR ra sp gp tp (Z_to_bv 64 (21 - kk)) (Z_to_bv 64 (kk - 10)) (Z_to_bv 64 (A0 + kk)) s0 (Z_to_bv 64 (hp_S1 p)) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 (-10)) (Z_to_bv 64 (hp_h p)) (Z_to_bv 64 21) (Z_to_bv 64 65296) (Z_to_bv 64 2147450880)
             (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_w p)) (Z_to_bv 64 10) (Z_to_bv 64 (hp_SP p)) t3 t4 (Z_to_bv 64 11) (Z_to_bv 64 (hp_wpl p * 4)))
        F (Z_to_bv 64 0xc2fa0) fc None m (seg_rom asegs)).
Proof.
