(* [comment removed for export] *)
Definition hp_A0 (p : hpp) (i j : Z) : Z := hp_LB p + 4 * hp_wpl p * i + j.
(* [comment removed for export] *)
Definition hp_LT (p : hpp) (i : Z) : Z := hp_DT p + 11 + (i + 11) * hp_wpl p * 4.

(* [comment removed for export] *)
Definition hp_j_exit (p : hpp) (i : Z) (ra sp gp tp s0 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a0' a1' t3' t4' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (hp_S1 p)) a0' a1' (Z_to_bv 64 i) (Z_to_bv 64 (hp_DT p + 11))
                  (Z_to_bv 64 (hp_LB p + 4 * hp_wpl p * i)) (Z_to_bv 64 (hp_w p)) (Z_to_bv 64 (hp_LT p i)) (Z_to_bv 64 (hp_A0 p i (hp_w p)))
                  (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 (-10)) (Z_to_bv 64 (hp_h p)) (Z_to_bv 64 21) (Z_to_bv 64 65296) (Z_to_bv 64 2147450880)
                  (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_w p)) (Z_to_bv 64 10) (Z_to_bv 64 (hp_SP p)) t3' t4' (Z_to_bv 64 11) (Z_to_bv 64 (hp_wpl p * 4)))
             F' (Z_to_bv 64 0xc2f34) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch [(hp_DT p, hp_DT p + hp_N p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma hp_j_loop : forall (n : nat) (p : hpp) (i j : Z)
    (ra sp gp tp t0 t1 t2 s0 a0 a1 t3 t4 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = hp_w p - j -> 0 <= j -> (1 <= n)%nat -> 0 <= i < hp_h p -> hp_ok p -> frm0 fc ->
  (forall m', munch [(hp_DT p, hp_DT p + hp_N p)] m m' -> wmono asegs m m' -> hp_ro p m') ->
  wr_at asegs m (hp_DT p) (hp_N p) -> acc asegs m (hp_DT p) (hp_N p) -> mem_inv asegs m ->
  evt asegs (hp_j_exit p i ra sp gp tp s0 F m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (hp_S1 p)) a0 a1 (Z_to_bv 64 i) (Z_to_bv 64 (hp_DT p + 11))
             (Z_to_bv 64 (hp_LB p + 4 * hp_wpl p * i)) (Z_to_bv 64 j) (Z_to_bv 64 (hp_LT p i)) (Z_to_bv 64 (hp_A0 p i j))
             (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 (-10)) (Z_to_bv 64 (hp_h p)) (Z_to_bv 64 21) (Z_to_bv 64 65296) (Z_to_bv 64 2147450880)
             (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_w p)) (Z_to_bv 64 10) (Z_to_bv 64 (hp_SP p)) t3 t4 (Z_to_bv 64 11) (Z_to_bv 64 (hp_wpl p * 4)))
        F (Z_to_bv 64 0xc2f88) fc None m (seg_rom asegs)).
Proof.
